{
  "items": [
    {
      "name": "MvPolynomial.eval_toMvPolynomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_3} [inst : CommSemiring R] (f : σ → R) (i : σ) (p : Polynomial R),\n  (MvPolynomial.eval f) ((Polynomial.toMvPolynomial i) p) = Polynomial.eval (f i) p"
    },
    {
      "name": "Polynomial.eval_C_X_eval₂_map_C_X",
      "module_name": "Mathlib.Algebra.Polynomial.Bivariate",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] {p : Polynomial (Polynomial R)},\n  Polynomial.eval (Polynomial.C Polynomial.X)\n      (Polynomial.eval₂ (Polynomial.mapRingHom (algebraMap R (Polynomial (Polynomial R)))) (Polynomial.C Polynomial.X)\n        p) =\n    p"
    },
    {
      "name": "MvPolynomial.evalₗ",
      "module_name": "Mathlib.FieldTheory.Finite.Polynomial",
      "kind": "definition",
      "type": "(K : Type u_1) → (σ : Type u_2) → [inst : CommSemiring K] → MvPolynomial σ K →ₗ[K] (σ → K) → K"
    },
    {
      "name": "Polynomial.eval",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Defs",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → R → Polynomial R → R"
    },
    {
      "name": "MvPolynomial.eval_comp_toMvPolynomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_3} [inst : CommSemiring R] (f : σ → R) (i : σ),\n  (MvPolynomial.eval f).comp ↑(Polynomial.toMvPolynomial i) = Polynomial.evalRingHom (f i)"
    }
  ]
}
